const http = require("http");
const fs = require("fs");
const os = require("os");
const path = require("path");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const ACCOUNT = "0123456789abcdef0123456789abcdef";
let created = false;
const server = http.createServer((req, res) => {
  req.resume();
  req.on("end", () => {
    res.setHeader("content-type", "application/json");
    if (req.method === "POST" && req.url.split("?")[0].endsWith("/accounts/" + ACCOUNT + "/pages/projects")) {
      created = true;
      res.end(JSON.stringify({ success: true, errors: [], messages: [], result: { name: "demo-proj", subdomain: "demo-proj.pages.dev" } }));
      return;
    }
    res.end(JSON.stringify({ success: true, errors: [], messages: [], result: [] }));
  });
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const cwd = fs.mkdtempSync(path.join(os.tmpdir(), "pf-"));
  const env = Object.assign({}, process.env, {
    CLOUDFLARE_API_TOKEN: "test-token",
    CLOUDFLARE_ACCOUNT_ID: ACCOUNT,
    CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4",
    WRANGLER_SEND_METRICS: "false",
    WRANGLER_SEND_ERROR_REPORTS: "false",
    PI_CODING_AGENT: "true",
    NO_COLOR: "1",
  });
  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "pages", "project", "create", "demo-proj", "--production-branch", "main", "--force"], { cwd, env, stdio: ["ignore", "pipe", "pipe"] });
  let out = "";
  child.stdout.on("data", (d) => (out += d));
  child.stderr.on("data", (d) => (out += d));
  const timer = setTimeout(() => { child.kill("SIGKILL"); broken("wrangler timed out: " + out.slice(-500)); }, 80000);
  child.on("close", (code) => {
    clearTimeout(timer);
    server.close();
    if (code !== 0 || !created || !out.includes("Successfully created the 'demo-proj' project")) broken("project create did not succeed (exit " + code + "): " + out.slice(-800));
    if (!out.includes("This is the only time you need --force")) symptom("no notice that --force is only needed once after a successful pages project create --force");
    console.log("OK: wrangler printed the one-time --force notice");
    process.exit(0);
  });
});

